 import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.name = config.id || 'primary-cta';

  const { PlaneGeometry, Mesh, DoubleSide, SRGBColorSpace } = ctx.THREE;

  // Atlas source rect: 512 x 320
  const texAspect = 512 / 320;
  const width = 2.4;
  const height = width / texAspect;

  const geometry = new PlaneGeometry(width, height, 1, 1);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1,
    side: DoubleSide,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  mesh.name = 'cta-plane';
  group.add(mesh);

  const timelines = [];

  const loadedTexture = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : null;

  if (loadedTexture) {
    loadedTexture
      .then((tex) => {
        if (!tex) return;
        tex.colorSpace = SRGBColorSpace;
        tex.needsUpdate = true;
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      try {
        tl?.kill();
      } catch (e) {}
    });

    geometry.dispose();
    if (material.map) {
      material.map.dispose();
      material.map = null;
    }
    material.dispose();
  };

  return group;
}
